// Copyright 2024 Apheleia
//
// Description:
// Apheleia Verification Library (AVL) Benchmark
//
// List constraints - set membership with "inside", and nothing else. Value
// sets, range sets, exclusion, and a set built from other random fields.
//
// This file is compiled unchanged by both flavours of the benchmark. Clock and
// reset are generated by the cocotb testbench in ../cocotb/list.py, which also
// runs the iteration loop, so the two flavours share an identical harness.
//
// Only the randomization itself differs, and it is the sole thing inside the
// `ifdef below.

`timescale 1ns/1ps

module list_bench (
    input logic clk,
    input logic rst_n
);

    // Common to both flavours - lets the testbench confirm that both ran for
    // the same number of clock cycles.
    int unsigned cycles = 0;

    always @(posedge clk) begin
        if (!rst_n) begin
            cycles <= 0;
        end
        else begin
            cycles <= cycles + 1;
        end
    end

`ifdef BENCH_SV_RANDOMIZE
    // -----------------------------------------------------------------------
    // Randomization under test - SystemVerilog classes and constraints.
    // -----------------------------------------------------------------------

    class list_item;

        rand bit [15:0] a;
        rand bit [15:0] b;
        rand bit [15:0] c;
        rand bit [15:0] d;

        // Every constraint here controls a single variable - there are no
        // dependencies between the fields. See the implication benchmark for
        // those.

        // A set of sixteen discrete values.
        constraint c_a { a inside {16'd1,    16'd2,    16'd4,    16'd8,
                                   16'd16,   16'd32,   16'd64,   16'd128,
                                   16'd256,  16'd512,  16'd1024, 16'd2048,
                                   16'd4096, 16'd8192, 16'd16384, 16'd32768}; }

        // A set of ranges.
        constraint c_b { b inside {[16'd100:16'd200], [16'd500:16'd600],
                                   [16'd5000:16'd5100]}; }

        // Exclusion - anything outside the range.
        constraint c_c { !(c inside {[16'd0:16'd1000]}); }

        // A set mixing discrete values with a range.
        constraint c_d { d inside {16'd7, [16'd20:16'd25], 16'd9999}; }

    endclass : list_item

    list_item        item;
    bit              enable   = 1'b1;
    int unsigned     burst    = 1;
    longint unsigned checksum = 0;
    int unsigned     count    = 0;

    initial begin
        item = new();
        // Cleared for the baseline run, which measures the harness on its own.
        void'($value$plusargs("randomize=%d", enable));
        void'($value$plusargs("burst=%d", burst));
    end

    always @(posedge clk) begin
        if (rst_n && enable) begin
            repeat (burst) begin
                if (item.randomize() == 0) begin
                    $fatal(1, "randomization failed on iteration %0d", count);
                end

                if (!(item.a inside {16'd1,    16'd2,    16'd4,    16'd8,
                                     16'd16,   16'd32,   16'd64,   16'd128,
                                     16'd256,  16'd512,  16'd1024, 16'd2048,
                                     16'd4096, 16'd8192, 16'd16384, 16'd32768})) begin
                    $fatal(1, "c_a violated : a=%0d", item.a);
                end
                if (!(item.b inside {[16'd100:16'd200], [16'd500:16'd600],
                                     [16'd5000:16'd5100]})) begin
                    $fatal(1, "c_b violated : b=%0d", item.b);
                end
                if (item.c inside {[16'd0:16'd1000]}) begin
                    $fatal(1, "c_c violated : c=%0d", item.c);
                end
                if (!(item.d inside {16'd7, [16'd20:16'd25], 16'd9999})) begin
                    $fatal(1, "c_d violated : d=%0d", item.d);
                end

                checksum += 64'(item.a) + 64'(item.b) + 64'(item.c) + 64'(item.d);
                count    += 1;
            end
        end
    end

    final begin
        $display("BENCH_RESULT flavour=sv iterations=%0d checksum=%0d", count, checksum);
    end
`endif

endmodule : list_bench
